INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6e31508e-9491-5f81-99a3-c7ed19c7b0bd', 'Notice to Lessees and Operators of Federal Oil', 'Notice to Lessees and Operators of Federal Oil, Gas, and Sulphur Leases and Pipeline Right-of-Way Holders Outer Continental Shelf, Gulf of Mexico OCS Region', 'This notice provides guidance on using either e-mail or the eWell Permitting and Reporting System to report hurricane and tropical storm effects information and specifies the information included in the various hurricane and tropical storm reports. and makes minor administrative amendments.', 'This notice provides guidance on using either e-mail or the eWell Permitting and Reporting System to report hurricane and tropical storm effects information and specifies the information included in the various hurricane and tropical storm reports. and makes minor administrative amendments.', 'This notice provides guidance on using either e-mail or the eWell Permitting and Reporting System to report hurricane and tropical storm effects information and specifies the information included in the various hurricane and tropical storm reports. and makes minor administrative amendments.', 'USA', 'climate', 'in_force', '2015-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_76', ARRAY['usa', 'guidance_frameworks', 'mandatory', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d58b503f-be2c-5d4a-81ab-d493c0432803', 'USA Guide to Conducting and Analyzing a Food Waste', 'A Guide to Conducting and Analyzing a Food Waste Assessment, 2014', 'This guide explains how to conduct a food waste assessment. This information provides the steps necessary to achieve a baseline measurement which can be used to set goals and track your organization’s progress.', 'This guide explains how to conduct a food waste assessment. This information provides the steps necessary to achieve a baseline measurement which can be used to set goals and track your organization’s progress.', 'This guide explains how to conduct a food waste assessment. This information provides the steps necessary to achieve a baseline measurement which can be used to set goals and track your organization’s progress.', 'USA', 'nature', 'in_force', '2014-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_71', ARRAY['other sustainability policy', 'mandatory', 'usa', 'mandatory_regulations', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d8409fe6-5ef4-545d-bbc4-5af234f0db0a', 'USA Assessing Biogenic CO2 Emissions from Stationary Sources', 'Framework for Assessing Biogenic CO2 Emissions from Stationary Sources, 2014', 'This report presents a methodological framework for assessing the extent to which the production, processing, and use of biogenic material at stationary sources results in a net atmospheric contribution of biogenic carbon dioxide (CO2) emissions. The framework examines direct emissions of biogenic CO2 from stationary sources that combust or process biogenic material, taking into account factors related to the biological carbon cycle.', 'This report presents a methodological framework for assessing the extent to which the production, processing, and use of biogenic material at stationary sources results in a net atmospheric contribution of biogenic carbon dioxide (CO2) emissions. The framework examines direct emissions of biogenic CO2 from stationary sources that combust or process biogenic material, taking into account factors related to the biological carbon cycle.', 'This report presents a methodological framework for assessing the extent to which the production, processing, and use of biogenic material at stationary sources results in a net atmospheric contribution of biogenic carbon dioxide (CO2) emissions. The framework examines direct emissions of biogenic CO2 from stationary sources that combust or process biogenic material, taking into account factors related to the biological carbon cycle.', 'USA', 'climate', 'in_force', '2014-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_72', ARRAY['sdg13', 'other sustainability policy', 'voluntary', 'usa', 'sdg12', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c8b07546-8c33-562d-8436-7e5bb64961e3', 'USA Report on Review of Disclosure Requirements in Regulation', 'Report on Review of Disclosure Requirements in Regulation S-K', 'The rule requires SEC registrants to disclose in their proxy statements the median of the annual total compensation of all employees (other than the chief executive officer) and the ratio of the median to the chief executive officer’s annual total compensation.', 'The rule requires SEC registrants to disclose in their proxy statements the median of the annual total compensation of all employees (other than the chief executive officer) and the ratio of the median to the chief executive officer’s annual total compensation.', 'The rule requires SEC registrants to disclose in their proxy statements the median of the annual total compensation of all employees (other than the chief executive officer) and the ratio of the median to the chief executive officer’s annual total compensation.', 'USA', 'climate', 'in_force', '2013-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_11', ARRAY['usa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
