INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6d66f0d9-556d-524b-8da1-0705d6639564', 'USA Renewable Fuel Standard (RFS): Overview and Issues', 'Renewable Fuel Standard (RFS): Overview and Issues, 2013', 'This report describes the general nature of the RFS mandate and its implementation, and outlines some emerging issues related to the continued growth of U.S. biofuels production needed to fulfill the expanding RFS mandate, as well as the emergence of potential unintended consequences of this rapid expansion.', 'This report describes the general nature of the RFS mandate and its implementation, and outlines some emerging issues related to the continued growth of U.S. biofuels production needed to fulfill the expanding RFS mandate, as well as the emergence of potential unintended consequences of this rapid expansion.', 'This report describes the general nature of the RFS mandate and its implementation, and outlines some emerging issues related to the continued growth of U.S. biofuels production needed to fulfill the expanding RFS mandate, as well as the emergence of potential unintended consequences of this rapid expansion.', 'USA', 'climate', 'in_force', '2013-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_70', ARRAY['sdg14', 'other sustainability policy', 'sdg7', 'voluntary', 'usa', 'sdg12', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6517d088-bfbd-5076-bbaf-b1ea5bc5148e', 'USA Conflict Minerals (SEC, 2012) – Implementing Section 1502', 'Conflict Minerals (SEC, 2012) – Implementing Section 1502 of the Dodd-Frank Wall Street Reform and Consumer Protection Act', 'The SEC Final Rule on Conflict Minerals establishes disclosure requirements for U.S. publicly traded companies that use conflict minerals (tantalum, tin, tungsten, and gold—3TG) in their products. It implements Section 1502 of the Dodd-Frank Act to prevent financing of armed groups in the Democratic Republic of the Congo (DRC) and adjoining countries.

Key provisions include:

Applicability:
Covers issuers filing reports under Sections 13(a) or 15(d) of the Securities Exchange Act of 1934.
Applies to companies manufacturing or contracting to manufacture products containing 3TG minerals.
Three-Step Compliance Process:
Step 1: Determine Applicability – If conflict minerals are necessary to a product’s functionality or production, the company must proceed to Step 2.
Step 2: Reasonable Country of Origin Inquiry (RCOI) – Businesses must determine if 3TG minerals originate from the DRC or adjoining countries. If so, they proceed to Step 3.
Step 3: Conflict Minerals Report (CMR) & Due Diligence:
Companies sourcing from covered countries must file a Conflict Minerals Report (CMR).
The report must describe due diligence measures, including supply chain audits.
Companies must publicly disclose findings on their website.
Independent Audit Requirement:
If minerals are not classified as “DRC conflict-free”, companies must conduct an independent private sector audit (IPSA).
Auditors must follow standards set by the U.S. Government Accountability Office (GAO).
Disclosure & Reporting:
Annual filings via Form SD to the SEC by May 31 each year.
Required disclosures include:
Origin of conflict minerals.
Facilities used to process the minerals.
Efforts taken to determine mine locations.
Compliance Timeline:
The rule became effective on November 13, 2012.
Companies had to comply starting January 1, 2013, with the first reports due May 31, 2014.
The rule aims to enhance supply chain transparency, promote responsible sourcing, and prevent funding of armed conflicts.', 'The SEC Final Rule on Conflict Minerals establishes disclosure requirements for U.S. publicly traded companies that use conflict minerals (tantalum, tin, tungsten, and gold—3TG) in their products. It implements Section 1502 of the Dodd-Frank Act to prevent financing of armed groups in the Democratic Republic of the Congo (DRC) and adjoining countries.

