INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('34b152de-f35a-56ba-8f28-595ccd3174da', 'USA Principles of Corporate Governance', 'Principles of Corporate Governance, 2012', 'This is the 2012 version of the Business Roundtable principles which are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts for the public dialogue on evolving governance standards.', 'This is the 2012 version of the Business Roundtable principles which are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts for the public dialogue on evolving governance standards.', 'This is the 2012 version of the Business Roundtable principles which are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts for the public dialogue on evolving governance standards.', 'USA', 'governance', 'in_force', '2012-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_37', ARRAY['guidance_frameworks', 'other sustainability policy', 'usa', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f773fae3-1678-5190-9c23-d065d0360025', 'USA ECMPS Reporting Requirements Related to the Amendments', 'ECMPS Reporting Requirements Related to the Amendments to the Protocol Gas Verification Program and Minimum Competency Requirements for Air Emissions Testing, 2012', 'The purpose of this document is to provide guidance for complying with the Emission Collection and Monitoring Plan System (ECMPS) reporting requirements related to the amendments to the Protocol Gas Verification Program (PGVP) and Minimum Competency Requirements for Air Emissions Testing (AETB).', 'The purpose of this document is to provide guidance for complying with the Emission Collection and Monitoring Plan System (ECMPS) reporting requirements related to the amendments to the Protocol Gas Verification Program (PGVP) and Minimum Competency Requirements for Air Emissions Testing (AETB).', 'The purpose of this document is to provide guidance for complying with the Emission Collection and Monitoring Plan System (ECMPS) reporting requirements related to the amendments to the Protocol Gas Verification Program (PGVP) and Minimum Competency Requirements for Air Emissions Testing (AETB).', 'USA', 'climate', 'in_force', '2012-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_64', ARRAY['sdg13', 'mandatory', 'usa', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
