INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4a64aedd-d71b-5df3-a52e-01fc18a887d8', 'USA Landfill Gas Energy A Guide to Developing', 'Landfill Gas Energy A Guide to Developing and Implementing Greenhouse Gas Reduction Programs, 2012', 'This guide describes how local governments and communities can achieve energy, environmental, health, and economic benefits by using landfill gas (LFG) recovered from municipal solid waste landfills as a source of renewable energy.', 'This guide describes how local governments and communities can achieve energy, environmental, health, and economic benefits by using landfill gas (LFG) recovered from municipal solid waste landfills as a source of renewable energy.', 'This guide describes how local governments and communities can achieve energy, environmental, health, and economic benefits by using landfill gas (LFG) recovered from municipal solid waste landfills as a source of renewable energy.', 'USA', 'climate', 'in_force', '2012-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_67', ARRAY['sdg13', 'other sustainability policy', 'sdg7', 'sdg11', 'mandatory', 'usa', 'mandatory_regulations', 'sdg12', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7508310f-9d0b-505a-b5da-e8ab5f83157c', 'USA Part 711 - TSCA Chemical Data Reporting Requirements', 'Part 711 - TSCA Chemical Data Reporting Requirements', 'It requires manufacturers (including importers) to provide the EPA information on the chemicals they manufacture domestically or import into the United States. EPA uses the data to help assess the potential human health and environmental effects of these chemicals.', 'It requires manufacturers (including importers) to provide the EPA information on the chemicals they manufacture domestically or import into the United States. EPA uses the data to help assess the potential human health and environmental effects of these chemicals.', 'It requires manufacturers (including importers) to provide the EPA information on the chemicals they manufacture domestically or import into the United States. EPA uses the data to help assess the potential human health and environmental effects of these chemicals.', 'USA', 'climate', 'in_force', '2011-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_14', ARRAY['mandatory', 'usa', 'mandatory_regulations', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('623d6296-3453-5abd-bb45-95e4105ae0de', 'USA Title 40: Protection of Environment - Part 75—', 'Title 40: Protection of Environment - Part 75— Continuous Emission Monitoring, 2011', 'Part 75 establishes requirements for the monitoring, recordkeeping, and reporting of sulfur dioxide, nitrogen oxides, and carbon dioxide emissions, volumetric flow, and opacity data from affected units under the Acid Rain Program pursuant to sections 412 and 821 of the CAA, 42 U.S.C. 7401-7671q as amended by Public Law 101-549. In addition, this part sets forth provisions for the monitoring, recordkeeping, and reporting of NOX mass emissions with which EPA, individual States, or groups of States may require sources to comply in order to demonstrate compliance with a NOX mass emission reduction program, to the extent these provisions are adopted as requirements under such a program. The regulations include general requirements for the installation, certification, operation, and maintenance of continuous emission or opacity monitoring systems and specific requirements for the monitoring of emissions, volumetric flow, opacity, by qualifying Phase I technologies. Specifications for the installation and performance of continuous emission monitoring systems, certification tests and procedures, and quality assurance tests and procedures are included in appendices A and B.', 'Part 75 establishes requirements for the monitoring, recordkeeping, and reporting of sulfur dioxide, nitrogen oxides, and carbon dioxide emissions, volumetric flow, and opacity data from affected units under the Acid Rain Program pursuant to sections 412 and 821 of the CAA, 42 U.S.C. 7401-7671q as amended by Public Law 101-549. In addition, this part sets forth provisions for the monitoring, recordkeeping, and reporting of NOX mass emissions with which EPA, individual States, or groups of States may require sources to comply in order to demonstrate compliance with a NOX mass emission reduction program, to the extent these provisions are adopted as requirements under such a program. The regulations include general requirements for the installation, certification, operation, and maintenance of continuous emission or opacity monitoring systems and specific requirements for the monitoring of emissions, volumetric flow, opacity, by qualifying Phase I technologies. Specifications for the installation and performance of continuous emission monitoring systems, certification tests and procedures, and quality assurance tests and procedures are included in appendices A and B.', 'Part 75 establishes requirements for the monitoring, recordkeeping, and reporting of sulfur dioxide, nitrogen oxides, and carbon dioxide emissions, volumetric flow, and opacity data from affected units under the Acid Rain Program pursuant to sections 412 and 821 of the CAA, 42 U.S.C. 7401-7671q as amended by Public Law 101-549. In addition, this part sets forth provisions for the monitoring, recordkeeping, and reporting of NOX mass emissions with which EPA, individual States, or groups of States may require sources to comply in order to demonstrate compliance with a NOX mass emission reduction program, to the extent these provisions are adopted as requirements under such a program. The regulations include general requirements for the installation, certification, operation, and maintenance of continuous emission or opacity monitoring systems and specific requirements for the monitoring of emissions, volumetric flow, opacity, by qualifying Phase I technologies. Specifications for the installation and performance of continuous emission monitoring systems, certification tests and procedures, and quality assurance tests and procedures are included in appendices A and B.', 'USA', 'climate', 'in_force', '2011-01-01'::date, 'United States', 'https://www.carrots