INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6e8bb86e-28e3-5807-9612-0abed6416f90', 'USA Process Safety Leading and Lagging Metrics', 'Process Safety Leading and Lagging Metrics, 2011', 'This document describes the recommendations assembled by the Center for Chemical Process Safety (CCPS) Process Safety Metric committee for a common set of company and industry leading and lagging metrics.', 'This document describes the recommendations assembled by the Center for Chemical Process Safety (CCPS) Process Safety Metric committee for a common set of company and industry leading and lagging metrics.', 'This document describes the recommendations assembled by the Center for Chemical Process Safety (CCPS) Process Safety Metric committee for a common set of company and industry leading and lagging metrics.', 'USA', 'governance', 'in_force', '2011-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_60', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'usa', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('640c364c-8fa9-54af-88da-89f29a8ed895', 'USA Toxics Release Inventory', 'Toxics Release Inventory, 2011', 'This Information Collection Request (ICR) is for the information collection requirements associated with EPA’s Toxics Release Inventory (TRI) Program. Pursuant to section 313 of EPCRA, certain facilities that manufacture, process, or otherwise use specified toxic chemicals in amounts above reporting threshold levels must submit annually to EPA and to designated State officials toxic chemical release forms containing information specified by EPA. 42 U.S.C. 11023.', 'This Information Collection Request (ICR) is for the information collection requirements associated with EPA’s Toxics Release Inventory (TRI) Program. Pursuant to section 313 of EPCRA, certain facilities that manufacture, process, or otherwise use specified toxic chemicals in amounts above reporting threshold levels must submit annually to EPA and to designated State officials toxic chemical release forms containing information specified by EPA. 42 U.S.C. 11023.', 'This Information Collection Request (ICR) is for the information collection requirements associated with EPA’s Toxics Release Inventory (TRI) Program. Pursuant to section 313 of EPCRA, certain facilities that manufacture, process, or otherwise use specified toxic chemicals in amounts above reporting threshold levels must submit annually to EPA and to designated State officials toxic chemical release forms containing information specified by EPA. 42 U.S.C. 11023.', 'USA', 'climate', 'in_force', '2011-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_62', ARRAY['usa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('59423a02-5830-5ac2-84f2-7e7a5e95fadc', 'USA Calculating Job Placement Rates Under Gainful Employment Regulations', 'Calculating Job Placement Rates Under Gainful Employment Regulations, 2011', 'The purpose of this background paper is to present information on options available for developing a methodology that institutions would use to calculate job placement rates they are required to disclose under the new regulations. In addition, the paper discusses whether in addition to disclosing the data, institutions should report job placement rates for gainful employment programs to IPEDS, and if so, how the collection of the data could be incorporated into the data collection.', 'The purpose of this background paper is to present information on options available for developing a methodology that institutions would use to calculate job placement rates they are required to disclose under the new regulations. In addition, the paper discusses whether in addition to disclosing the data, institutions should report job placement rates for gainful employment programs to IPEDS, and if so, how the collection of the data could be incorporated into the data collection.', 'The purpose of this background paper is to present information on options available for developing a methodology that institutions would use to calculate job placement rates they are required to disclose under the new regulations. In addition, the paper discusses whether in addition to disclosing the data, institutions should report job placement rates for gainful employment programs to IPEDS, and if so, how the collection of the data could be incorporated into the data collection.', 'USA', 'climate', 'in_force', '2011-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_63', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'usa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('454868bf-9b11-56ca-9aad-844e49860712', 'USA Senate Bill An act to add Section 1714.43', 'Senate Bill No. 657 An act to add Section 1714.43 to the Civil Code, and to add Section 19547.5 to the Revenue and Taxation Code, relating to human trafficking.', 'This document is concerned with a senate bill which outlines an act to add Section 1714.43 to the Civil Code, and to add Section 19547.5 to the Revenue and Taxation Code, relating to human trafficking.', 'This document is concerned with a senate bill which outlines an act to add Section 1714.43 to the Civil Code, and to add Section 19547.5 to the Revenue and Taxation Code, relating to human trafficking.', 'This document is concerned with a senate bill which outlines an act to add Section 1714.43 to the Civil Code, and to add Section 19547.5 to the Revenue and Taxation Code, relating to human trafficking.', 'USA', 'governance', 'in_force', '2010-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_12', ARRAY['usa', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('625497f3-5022-5567-a5bb-d31142d4f49d', 'USA 17 CFR Parts 211, 231 and 241 Commission', '17 CFR Parts 211, 231 and 241 Commission Guidance Regarding Disclosure Related to Climate Change; Final Rule', 'The Securities and Exchange Commission (‘‘SEC’’ or ‘‘Commission’’) published this interpretive release to provide guidance to public companies regarding the Commission’s existing disclosure requirements as they apply to climate change matters.', 'The Securities and Exchange Commission (‘‘SEC’’ or ‘‘Commission’’) published this interpretive release to provide guidance to public companies regarding the Commission’s existing disclosure requirements as they apply to climate change matters.', 'The Securities and Exchange Commission (‘‘SEC’’ or ‘‘Commission’’) published this interpretive release to provide guidance to public companies regarding the Commission’s existing disclosure requirements as they apply to climate change matters.', 'USA', 'climate', 'in_force', '2010-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_13', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'mandatory', 'usa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('548ad7a1-ebdc-5bdf-b049-b7dd297770e8', 'Report of the New York Stock Exchange Commission', 'Report of the New York Stock Exchange Commission on Corporate Governance, 2010', 'The NYSE''s listing standards have included governance rules for approximately 150 years. The first decade of the 21st century has seen more changes in the governance landscape than at any time since perhaps the Great Depression. During this period the NYSE has continued to foster innovative solutions to critical governance issues. The NYSE established the Proxy Working Group ("PWG") to review the voting and proxy process. The PWG''s reports made a number of recommendations to both the NYSE and the SEC. These recommendations were included in the SEC''s "Proxy Plumbing" concept release in July 2010.', 'The NYSE''s listing standards have included governance rules for approximately 150 years. The first decade of the 21st century has seen more changes in the governance landscape than at any time since perhaps the Great Depression. During this period the NYSE has continued to foster innovative solutions to critical governance issues. The NYSE established the Proxy Working Group ("PWG") to review the voting and proxy process. The PWG''s reports made a number of recommendations to both the NYSE and the SEC. These recommendations were included in the SEC''s "Proxy Plumbing" concept release in July 2010.', 'The NYSE''s listing standards have included governance rules for approximately 150 years. The first decade of the 21st century has seen more changes in the governance landscape than at any time since perhaps the Great Depression. During this period the NYSE has continued to foster innovative solutions to critical governance issues. The NYSE established the Proxy Working Group ("PWG") to review the voting and proxy process. The PWG''s reports made a number of recommendations to both the NYSE and the SEC. These recommendations were included in the SEC''s "Proxy Plumbing" concept release in July 2010.', 'USA', 'climate', 'in_force', '2010-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_39', ARRAY['mandatory', 'usa', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4fea04cc-4742-50e7-9872-1a4470eafa6b', 'USA ECMPS Reporting Guidance for the GHG-MRR', 'ECMPS Reporting Guidance for the GHG-MRR, 2010', 'EPA will not be creating any new program code(s) in the ECMPS system for the MRR. Units that are not subject to the Acid Rain Program (ARP) or the Regional Greenhouse Gas Initiative (RGGI) must instead use one of the tiered options given in §98.33(a)(1) through (4) of Part 75. No changes are needed to either the electronic monitoring plans or the quarterly electronic data reports. Beginning on January 1, 2010, all emissions data (NOx , SO2 (if applicable), etc.) and heat input data for all units using the monitoring and reporting option in §98.33(a)(5) must be reported on the year-round or "annual" basis. If you elect not to report CO2 mass emissions data through ECMPS no further changes are required.', 'EPA will not be creating any new program code(s) in the ECMPS system for the MRR. Units that are not subject to the Acid Rain Program (ARP) or the Regional Greenhouse Gas Initiative (RGGI) must instead use one of the tiered options given in §98.33(a)(1) through (4) of Part 75. No changes are needed to either the electronic monitoring plans or the quarterly electronic data reports. Beginning on January 1, 2010, all emissions data (NOx , SO2 (if applicable), etc.) and heat input data for all units using the monitoring and reporting option in §98.33(a)(5) must be reported on the year-round or "annual" basis. If you elect not to report CO2 mass emissions data through ECMPS no further changes are required.', 'EPA will not be creating any new program code(s) in the ECMPS system for the MRR. Units that are not subject to the Acid Rain Program (ARP) or the Regional Greenhouse Gas Initiative (RGGI) must instead use one of the tiered options given in §98.33(a)(1) through (4) of Part 75. No changes are needed to either the electronic monitoring plans or the quarterly electronic data reports. Beginning on January 1, 2010, all emissions data (NOx , SO2 (if applicable), etc.) and heat input data for all units using the monitoring and reporting option in §98.33(a)(5) must be reported on the year-round or "annual" basis. If you elect not to report CO2 mass emissions data through ECMPS no further changes are required.', 'USA', 'climate', 'in_force', '2010-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_52', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'usa', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8160c887-1e6f-56b1-8748-14cfc27509ec', 'USA Part 260 - Guides for the Use', 'Part 260 - Guides for the Use of Environmental Marketing Claims, 2010', 'These guides set forth the Federal Trade Commission’s current views about environmental claims. The guides help marketers avoid making environmental marketing claims that are unfair or deceptive under Section 5 of the FTC Act, 15 U.S.C. § 45.', 'These guides set forth the Federal Trade Commission’s current views about environmental claims. The guides help marketers avoid making environmental marketing claims that are unfair or deceptive under Section 5 of the FTC Act, 15 U.S.C. § 45.', 'These guides set forth the Federal Trade Commission’s current views about environmental claims. The guides help marketers avoid making environmental marketing claims that are unfair or deceptive under Section 5 of the FTC Act, 15 U.S.C. § 45.', 'USA', 'governance', 'in_force', '2010-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_53', ARRAY['usa', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed0ce070-738f-52d3-902d-2d2ed8989989', 'USA Guide to Protecting the Confidentiality of Personally Identifiable', 'Guide to Protecting the Confidentiality of Personally Identifiable Information (PII), 2010', 'This document provides guidelines for a risk-based approach to protecting the confidentiality of PII. The recommendations in this document are intended primarily for U.S. Federal government agencies and those who conduct business on behalf of the agencies, but other organizations may find portions of the publication useful. Each organization may be subject to a different combination of laws, regulations, and other mandates related to protecting PII, so an organization‘s legal counsel and privacy officer should be consulted to determine the current obligations for PII protection.', 'This document provides guidelines for a risk-based approach to protecting the confidentiality of PII. The recommendations in this document are intended primarily for U.S. Federal government agencies and those who conduct business on behalf of the agencies, but other organizations may find portions of the publication useful. Each organization may be subject to a different combination of laws, regulations, and other mandates related to protecting PII, so an organization‘s legal counsel and privacy officer should be consulted to determine the current obligations for PII protection.', 'This document provides guidelines for a risk-based approach to protecting the confidentiality of PII. The recommendations in this document are intended primarily for U.S. Federal government agencies and those who conduct business on behalf of the agencies, but other organizations may find portions of the publication useful. Each organization may be subject to a different combination of laws, regulations, and other mandates related to protecting PII, so an organization‘s legal counsel and privacy officer should be consulted to determine the current obligations for PII protection.', 'USA', 'climate', 'in_force', '2010-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_59', ARRAY['usa', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7b583aaf-f38d-5697-b41f-b8aa590057f4', 'Executive Order 13514 -- Federal Leadership in Environmental', 'Executive Order 13514 -- Federal Leadership in Environmental, Energy, and Economic Performance', 'Executive Order 13514 required the Federal agencies to measure and reduce greenhouse gas emissions resulting from Federal operations, improve energy efficiency, increase use of renewable energy, reduce water consumption, and purchase energy efficient and environmentally preferable goods and materials.', 'Executive Order 13514 required the Federal agencies to measure and reduce greenhouse gas emissions resulting from Federal operations, improve energy efficiency, increase use of renewable energy, reduce water consumption, and purchase energy efficient and environmentally preferable goods and materials.', 'Executive Order 13514 required the Federal agencies to measure and reduce greenhouse gas emissions resulting from Federal operations, improve energy efficiency, increase use of renewable energy, reduce water consumption, and purchase energy efficient and environmentally preferable goods and materials.', 'USA', 'climate', 'in_force', '2009-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_10', ARRAY['sdg13', 'other sustainability policy', 'sdg7', 'mandatory', 'sdg6', 'usa', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dc7cdcb1-6b41-52ef-a199-6d643f359479', 'USA EPA Mandatory Greenhouse Gas Reporting Program (GHGRP)', 'EPA Mandatory Greenhouse Gas Reporting Program (GHGRP)', 'The Mandatory Greenhouse Gas Reporting Program (GHGRP) was established by the Environmental Protection Agency (EPA) under 40 CFR Part 98, requiring certain facilities and suppliers to report their greenhouse gas (GHG) emissions. The regulation aims to improve data transparency, inform climate policies, and enhance emissions tracking.

Key provisions include:

Applicability & Scope:
Covers facilities emitting 25,000 metric tons or more of CO₂ equivalent (CO₂e) annually.
Includes suppliers of fossil fuels and industrial GHGs, as well as specific source categories.
Reporting Requirements:
Facilities must submit annual GHG reports to the EPA.
Emissions data must include:
Carbon dioxide (CO₂), methane (CH₄), nitrous oxide (N₂O), and fluorinated gases.
Source-specific emission factors, monitoring methods, and fuel usage data.
Reports must include:
U.S. parent company details.
North American Industry Classification System (NAICS) code(s).
Cogeneration unit emissions, if applicable.
Data Collection & Compliance:
Direct emitters must use continuous monitoring systems (CEMS) or calculation methodologies.
Suppliers must report quantities of fuels or gases sold and emissions potential.
Public Disclosure & Transparency:
The EPA publishes emissions data for public access, enhancing corporate accountability.
Enforcement & Penalties:
Facilities failing to comply face administrative penalties and enforcement actions under the Clean Air Act (CAA) Section 114.
GHGRP provides crucial emissions data that supports state and federal climate policies, corporate sustainability strategies, and international reporting frameworks.', 'The Mandatory Greenhouse Gas Reporting Program (GHGRP) was established by the Environmental Protection Agency (EPA) under 40 CFR Part 98, requiring certain facilities and suppliers to report their greenhouse gas (GHG) emissions. The regulation aims to improve data transparency, inform climate policies, and enhance emissions tracking.

