INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0ea35b48-8d12-5d79-8805-ecd3d6f5f8eb', 'USA Key Agreed Principles to Strengthen Corporate Governance', 'Key Agreed Principles to Strengthen Corporate Governance for U.S. Publicly Traded Companies, 2008', 'These Key Agreed Principles reflect the distillation and articulation of fundamental principles- based aspects of governance on which there appears to be broad consensus. They are intended to describe the current baseline consensus and thereby to help improve the quality of discussion and debate about governance issues that have not yet gained consensus.', 'These Key Agreed Principles reflect the distillation and articulation of fundamental principles- based aspects of governance on which there appears to be broad consensus. They are intended to describe the current baseline consensus and thereby to help improve the quality of discussion and debate about governance issues that have not yet gained consensus.', 'These Key Agreed Principles reflect the distillation and articulation of fundamental principles- based aspects of governance on which there appears to be broad consensus. They are intended to describe the current baseline consensus and thereby to help improve the quality of discussion and debate about governance issues that have not yet gained consensus.', 'USA', 'governance', 'in_force', '2008-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_25', ARRAY['guidance_frameworks', 'other sustainability policy', 'usa', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4c2832f4-262e-5c53-aa2c-a4238c35295a', 'USA TIAA-CREF Policy Statement on Corporate Governance', 'TIAA-CREF Policy Statement on Corporate Governance (2007)', 'This is the fifth edition of this Policy Statement, which is reviewed and revised periodically by the TIAA and CREF boards of trustees. This edition reflects current developments in corporate governance, social and environmental policy, technology, market structure, globalization, cross-border and emerging-market investing and proxy voting.', 'This is the fifth edition of this Policy Statement, which is reviewed and revised periodically by the TIAA and CREF boards of trustees. This edition reflects current developments in corporate governance, social and environmental policy, technology, market structure, globalization, cross-border and emerging-market investing and proxy voting.', 'This is the fifth edition of this Policy Statement, which is reviewed and revised periodically by the TIAA and CREF boards of trustees. This edition reflects current developments in corporate governance, social and environmental policy, technology, market structure, globalization, cross-border and emerging-market investing and proxy voting.', 'USA', 'governance', 'in_force', '2007-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_43', ARRAY['other sustainability policy', 'mandatory', 'usa', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8dec81e1-f771-5812-9474-345e160d937c', 'USA Oil Discharge Reporting Requirements', 'Oil Discharge Reporting Requirements, 2006', 'These Discharge of Oil requirements provide a framework for determining whether an oil discharge to inland and coastal waters or adjoining shorelines should be reported to the National Response Center. Although these reporting requirements were not changed by EPA’s recent modifications of the SPCC rule, this Fact Sheet will help facilities with the Reportable Discharge History criterion associated with the qualified facility option and the oil-filled operational equipment option offered in the recent SPCC modifications.', 'These Discharge of Oil requirements provide a framework for determining whether an oil discharge to inland and coastal waters or adjoining shorelines should be reported to the National Response Center. Although these reporting requirements were not changed by EPA’s recent modifications of the SPCC rule, this Fact Sheet will help facilities with the Reportable Discharge History criterion associated with the qualified facility option and the oil-filled operational equipment option offered in the recent SPCC modifications.', 'These Discharge of Oil requirements provide a framework for determining whether an oil discharge to inland and coastal waters or adjoining shorelines should be reported to the National Response Center. Although these reporting requirements were not changed by EPA’s recent modifications of the SPCC rule, this Fact Sheet will help facilities with the Reportable Discharge History criterion associated with the qualified facility option and the oil-filled operational equipment option offered in the recent SPCC modifications.', 'USA', 'climate', 'in_force', '2006-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_57', ARRAY['sdg14', 'mandatory', 'sdg6', 'usa', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1be478bf-9042-54a2-b33e-dcd4574a5e0a', 'USA Oil and Gas and Sulphur Operations in the', 'Oil and Gas and Sulphur Operations in the Outer Continental Shelf—Incident Reporting Requirements, 2006', 'This final rule revises the MMS requirements for reporting incidents associated with Outer Continental Shelf (OCS) oil and gas and sulphur operations. The revisions will clarify the requirements, and provide more precise definitions and reporting timeframes.', 'This final rule revises the MMS requirements for reporting incidents associated with Outer Continental Shelf (OCS) oil and gas and sulphur operations. The revisions will clarify the requirements, and provide more precise definitions and reporting timeframes.', 'This final rule revises the MMS requirements for reporting incidents associated with Outer Continental Shelf (OCS) oil and gas and sulphur operations. The revisions will clarify the requirements, and provide more precise definitions and reporting timeframes.', 'USA', 'climate', 'in_force', '2006-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_58', ARRAY['usa', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d1709121-c20d-58cb-99c3-53917e450137', 'USA Principles for a Strong Nuclear Safety Culture', 'Principles for a Strong Nuclear Safety Culture, 2004', 'These Principles for a Strong Nuclear Safety Culture describes the essential attributes of a healthy nuclear safety culture (hereafter “safety culture”), with the goal of creating a framework for open discussion and continuing evolution of safety culture throughout the commercial nuclear electric generating industry. The principles and associated attributes described have a strong basis in plant events.', 'These Principles for a Strong Nuclear Safety Culture describes the essential attributes of a healthy nuclear safety culture (hereafter “safety culture”), with the goal of creating a framework for open discussion and continuing evolution of safety culture throughout the commercial nuclear electric generating industry. The principles and associated attributes described have a strong basis in plant events.', 'These Principles for a Strong Nuclear Safety Culture describes the essential attributes of a healthy nuclear safety culture (hereafter “safety culture”), with the goal of creating a framework for open discussion and continuing evolution of safety culture throughout the commercial nuclear electric generating industry. The principles and associated attributes described have a strong basis in plant events.', 'USA', 'climate', 'in_force', '2004-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_56', ARRAY['guidance_frameworks', 'sdg3', 'other sustainability policy', 'usa', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('288f9bc6-716c-5393-a200-b02e4458f9a6', 'USA Commission on Public Trust and Private Enterprise', 'Commission on Public Trust and Private Enterprise, 2003', 'This report summarizes the rationale used by the Commission to arrive at its conclusions for the second of these issues: Corporate Governance: Principles, Recommendations and Specific Best Practice Suggestions.', 'This report summarizes the rationale used by the Commission to arrive at its conclusions for the second of these issues: Corporate Governance: Principles, Recommendations and Specific Best Practice Suggestions.', 'This report summarizes the rationale used by the Commission to arrive at its conclusions for the second of these issues: Corporate Governance: Principles, Recommendations and Specific Best Practice Suggestions.', 'USA', 'climate', 'in_force', '2003-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_28', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'usa', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5141ace6-f0c5-524a-a525-857423a2769f', 'USA Final NYSE Corporate Governance Rules', 'Final NYSE Corporate Governance Rules, 2003', 'This document contains the final corporate governance rules of the New York Stock Exchange approved by the SEC on November 4, 2003, other than Section 303A.08, which was filed separately and approved by the SEC on June 30, 2003.', 'This document contains the final corporate governance rules of the New York Stock Exchange approved by the SEC on November 4, 2003, other than Section 303A.08, which was filed separately and approved by the SEC on June 30, 2003.', 'This document contains the final corporate governance rules of the New York Stock Exchange approved by the SEC on November 4, 2003, other than Section 303A.08, which was filed separately and approved by the SEC on June 30, 2003.', 'USA', 'governance', 'in_force', '2003-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_33', ARRAY['mandatory', 'usa', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dea894d8-72df-59cd-b8de-e7518a8f1118', 'USA Restoring Trust', 'Restoring Trust, 2003', 'This document contains 78 individual recommendations. These cover the selection of directors, qualification, conflicts and independence standards for board members, the functioning of the board and its committees, establishment of the position of non-executive chairman, specific limits on compensation practices, equity compensation programs, accounting and disclosure issues, ethics and legal compliance programs and other areas.', 'This document contains 78 individual recommendations. These cover the selection of directors, qualification, conflicts and independence standards for board members, the functioning of the board and its committees, establishment of the position of non-executive chairman, specific limits on compensation practices, equity compensation programs, accounting and disclosure issues, ethics and legal compliance programs and other areas.', 'This document contains 78 individual recommendations. These cover the selection of directors, qualification, conflicts and independence standards for board members, the functioning of the board and its committees, establishment of the position of non-executive chairman, specific limits on compensation practices, equity compensation programs, accounting and disclosure issues, ethics and legal compliance programs and other areas.', 'USA', 'governance', 'in_force', '2003-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_40', ARRAY['usa', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e154f57a-ec2a-5ee6-830b-6a65b5464b16', 'USA Direct Emissions from Iron & Steel Production', 'Direct Emissions from Iron & Steel Production, 2003', 'The Climate Leaders Greenhouse Gas Inventory Protocol is based on the Greenhouse Gas Protocol (GHG Protocol) developed by the World Resources Institute (WRI) and the World Business Council for Sustainable Development (WBCSD). The GHG Protocol consists of corporate accounting and reporting standards and separate calculation tools.', 'The Climate Leaders Greenhouse Gas Inventory Protocol is based on the Greenhouse Gas Protocol (GHG Protocol) developed by the World Resources Institute (WRI) and the World Business Council for Sustainable Development (WBCSD). The GHG Protocol consists of corporate accounting and reporting standards and separate calculation tools.', 'The Climate Leaders Greenhouse Gas Inventory Protocol is based on the Greenhouse Gas Protocol (GHG Protocol) developed by the World Resources Institute (WRI) and the World Business Council for Sustainable Development (WBCSD). The GHG Protocol consists of corporate accounting and reporting standards and separate calculation tools.', 'USA', 'climate', 'in_force', '2003-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_54', ARRAY['sdg13', 'mandatory', 'usa', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3540cf70-87f0-5d97-8470-5cbce73825f5', 'USA Preparing A Complete & Sufficient Suspicious Activity Report', 'Guidance on Preparing A Complete & Sufficient Suspicious Activity Report Narrative, 2003', 'The purpose of this Suspicious Activity Report (SAR) is to report known or suspected violations of law or suspicious activity observed by financial institutions subject to the regulations of the Bank Secrecy Act (BSA). In many instances, SARs have been instrumental in enabling law enforcement to initiate or supplement major money laundering or terrorist financing investigations and other criminal cases.', 'The purpose of this Suspicious Activity Report (SAR) is to report known or suspected violations of law or suspicious activity observed by financial institutions subject to the regulations of the Bank Secrecy Act (BSA). In many instances, SARs have been instrumental in enabling law enforcement to initiate or supplement major money laundering or terrorist financing investigations and other criminal cases.', 'The purpose of this Suspicious Activity Report (SAR) is to report known or suspected violations of law or suspicious activity observed by financial institutions subject to the regulations of the Bank Secrecy Act (BSA). In many instances, SARs have been instrumental in enabling law enforcement to initiate or supplement major money laundering or terrorist financing investigations and other criminal cases.', 'USA', 'climate', 'in_force', '2003-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_55', ARRAY['usa', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f3a25aa1-5dca-5c21-b8b1-17b9453efff7', 'USA Corporate Governance Policies', 'Corporate Governance Policies, 2002', 'These Council of Institutional Investors’ corporate governance policies aim to establish goals and guidelines for the effective governance of publicly traded corporations. The policies include fundamental core policies that the Council believes should be implemented by all companies, general principles of shareholder rights and board accountability, and a number of more general position statements on various corporate governance issues.', 'These Council of Institutional Investors’ corporate governance policies aim to establish goals and guidelines for the effective governance of publicly traded corporations. The policies include fundamental core policies that the Council believes should be implemented by all companies, general principles of shareholder rights and board accountability, and a number of more general position statements on various corporate governance issues.', 'These Council of Institutional Investors’ corporate governance policies aim to establish goals and guidelines for the effective governance of publicly traded corporations. The policies include fundamental core policies that the Council believes should be implemented by all companies, general principles of shareholder rights and board accountability, and a number of more general position statements on various corporate governance issues.', 'USA', 'governance', 'in_force', '2002-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_30', ARRAY['guidance_frameworks', 'mandatory', 'usa', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('008286b9-1495-55ec-ad01-37a7a21a2deb', 'USA Corporate Governance Rule Proposals', 'Corporate Governance Rule Proposals, 2002', 'This document includes a principal text of the rule filing submitted by the Exchange to the Securities and Exchange Commission on August 16, 2002. It includes the proposed corporate governance standards, as well as the related changes made to certain other Exchange rules.', 'This document includes a principal text of the rule filing submitted by the Exchange to the Securities and Exchange Commission on August 16, 2002. It includes the proposed corporate governance standards, as well as the related changes made to certain other Exchange rules.', 'This document includes a principal text of the rule filing submitted by the Exchange to the Securities and Exchange Commission on August 16, 2002. It includes the proposed corporate governance standards, as well as the related changes made to certain other Exchange rules.', 'USA', 'governance', 'in_force', '2002-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_32', ARRAY['mandatory', 'usa', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('02e765f4-20b0-50c7-aa9a-224caeb0631a', 'USA Principles of Corporate Governance', 'Principles of Corporate Governance, 2002', 'The principles discussed in this document are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts for the public dialogue on evolving governance standards.', 'The principles discussed in this document are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts for the public dialogue on evolving governance standards.', 'The principles discussed in this document are intended to assist corporate management and boards of directors in their individual efforts to implement best practices of corporate governance, and also to serve as guideposts for the public dialogue on evolving governance standards.', 'USA', 'governance', 'in_force', '2002-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_36', ARRAY['guidance_frameworks', 'other sustainability policy', 'usa', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('589100a3-85de-57a8-8bdb-1eeb66153eb6', 'Federal Water Pollution Control Act', 'Federal Water Pollution Control Act', 'This document is concerned with an Act to provide for water pollution control activities in the Public Health Serv­ice of the Federal Security Agency and in the Federal Works Agency, and for other purposes.', 'This document is concerned with an Act to provide for water pollution control activities in the Public Health Serv­ice of the Federal Security Agency and in the Federal Works Agency, and for other purposes.', 'This document is concerned with an Act to provide for water pollution control activities in the Public Health Serv­ice of the Federal Security Agency and in the Federal Works Agency, and for other purposes.', 'USA', 'governance', 'in_force', '2002-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_7', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'usa', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cdc6f086-0159-5296-97a0-01caff8f8ff3', 'USA Sarbanes-Oxley Act of', 'Sarbanes-Oxley Act of 2002', 'This documet is concerned with an act to protect investors by improving the accuracy and reliability of corporate disclosures made pursuant to the securities laws, and for other purposes.', 'This documet is concerned with an act to protect investors by improving the accuracy and reliability of corporate disclosures made pursuant to the securities laws, and for other purposes.', 'This documet is concerned with an act to protect investors by improving the accuracy and reliability of corporate disclosures made pursuant to the securities laws, and for other purposes.', 'USA', 'governance', 'in_force', '2002-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_9', ARRAY['usa', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('38308078-1424-5768-9176-0a2cba2c4392', 'USA Section 313 of the Emergency Planning and Community', 'Section 313 of the Emergency Planning and Community Right-to-Know Act', 'The purpose of this guidance document is to assist facilities in SIC code 5169 (chemical and allied products wholesale) to comply with the reporting requirements of Section 313 of the Emergency Planning and Community Right-to-Know Act of 1986 (EPCRA) and of Section 6607 of the Pollution Prevention Act of 1990 (PPA), commonly referred to as the Toxic Release Inventory (TRI).', 'The purpose of this guidance document is to assist facilities in SIC code 5169 (chemical and allied products wholesale) to comply with the reporting requirements of Section 313 of the Emergency Planning and Community Right-to-Know Act of 1986 (EPCRA) and of Section 6607 of the Pollution Prevention Act of 1990 (PPA), commonly referred to as the Toxic Release Inventory (TRI).', 'The purpose of this guidance document is to assist facilities in SIC code 5169 (chemical and allied products wholesale) to comply with the reporting requirements of Section 313 of the Emergency Planning and Community Right-to-Know Act of 1986 (EPCRA) and of Section 6607 of the Pollution Prevention Act of 1990 (PPA), commonly referred to as the Toxic Release Inventory (TRI).', 'USA', 'climate', 'in_force', '1999-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_8', ARRAY['regulations', 'sdg11', 'mandatory', 'usa', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('561b78ee-31d2-54c4-a003-4ecfbd768cd2', 'USA Global Corporate Governance Principles', 'Global Corporate Governance Principles, 1998', 'The overriding objective of the corporation should be to optimize over time the returns to its shareowners. Where other considerations affect this objective, they should be clearly stated and disclosed. To achieve this objective, the corporation should endeavor to ensure the long-term viability of its business, and to manage effectively its relationships with stakeholders.', 'The overriding objective of the corporation should be to optimize over time the returns to its shareowners. Where other considerations affect this objective, they should be clearly stated and disclosed. To achieve this objective, the corporation should endeavor to ensure the long-term viability of its business, and to manage effectively its relationships with stakeholders.', 'The overriding objective of the corporation should be to optimize over time the returns to its shareowners. Where other considerations affect this objective, they should be clearly stated and disclosed. To achieve this objective, the corporation should endeavor to ensure the long-term viability of its business, and to manage effectively its relationships with stakeholders.', 'USA', 'governance', 'in_force', '1998-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_35', ARRAY['guidance_frameworks', 'other sustainability policy', 'usa', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a458a0b5-8a96-597e-95d0-972bba82c9df', 'USA Statement on Corporate Governance', 'Statement on Corporate Governance, 1997', 'The Business Roundtable is recognized as an authoritative voice on matters affecting large corporations. This publication summarizes its current views on governance issues, thus updating and building on the work of the past. In the seven years since its last publication on corporate governance many of the practices suggested for consideration have become more common.', 'The Business Roundtable is recognized as an authoritative voice on matters affecting large corporations. This publication summarizes its current views on governance issues, thus updating and building on the work of the past. In the seven years since its last publication on corporate governance many of the practices suggested for consideration have become more common.', 'The Business Roundtable is recognized as an authoritative voice on matters affecting large corporations. This publication summarizes its current views on governance issues, thus updating and building on the work of the past. In the seven years since its last publication on corporate governance many of the practices suggested for consideration have become more common.', 'USA', 'governance', 'in_force', '1997-01-01'::date, 'United States', 'https://www.carrotsandsticks.org/policies/185_41', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'usa', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3ff9676e-fa1c-5a95-8481-90b915804d99', 'Uruguay Decree Regulation on limitations on lead content', 'Decree No. 69/011 Regulation on limitations on lead content on paints and varnishes', 'The Decree establishes that any natural or legal person, private or public, who manufactures or imports paints, varnishes, graphical inks and masterbatches, must: A) register in Ministry of Housing, Territorial Planning and Environment, in accordance with the requirements and formalities established; B) submit to the National Environment Directorate a sworn statement declaring the content and formalities established, in which it must include, among other data, the lead content of paints, varnishes and graphical inks which it manufactures or imports.', 'The Decree establishes that any natural or legal person, private or public, who manufactures or imports paints, varnishes, graphical inks and masterbatches, must: A) register in Ministry of Housing, Territorial Planning and Environment, in accordance with the requirements and formalities established; B) submit to the National Environment Directorate a sworn statement declaring the content and formalities established, in which it must include, among other data, the lead content of paints, varnishes and graphical inks which it manufactures or imports.', 'The Decree establishes that any natural or legal person, private or public, who manufactures or imports paints, varnishes, graphical inks and masterbatches, must: A) register in Ministry of Housing, Territorial Planning and Environment, in accordance with the requirements and formalities established; B) submit to the National Environment Directorate a sworn statement declaring the content and formalities established, in which it must include, among other data, the lead content of paints, varnishes and graphical inks which it manufactures or imports.', 'Uruguay', 'climate', 'in_force', '2011-01-01'::date, 'Uruguay', 'https://www.carrotsandsticks.org/policies/186_1', ARRAY['other sustainability policy', 'regulations', 'uruguay', 'sdg11', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5e4b1347-033b-50e6-a15b-6b69169e7b47', 'Uruguay Decree Regulation on environmental impact and environmental authorizations', 'Decree No. 349/005 Regulation on environmental impact and environmental authorizations', 'Regulates the Environmental Authorization procedure prior to being requested for the execution of certain activities related to water resources.', 'Regulates the Environmental Authorization procedure prior to being requested for the execution of certain activities related to water resources.', 'Regulates the Environmental Authorization procedure prior to being requested for the execution of certain activities related to water resources.', 'Uruguay', 'governance', 'in_force', '2005-01-01'::date, 'Uruguay', 'https://www.carrotsandsticks.org/policies/186_2', ARRAY['regulations', 'uruguay', 'mandatory', 'sdg6', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c1fd6354-d0dd-5b14-b3ea-ffa2cce017f7', 'Uruguay Decree . Prohibition of Marketing of Products Containing', 'Decree No. 154/002. Prohibition of Marketing of Products Containing Asbestos or Asbestos', 'Decree No. 154/002 establishes that for the manufacture, introduction into the national territory under any form, and marketing of asbestos or products which contain it, authorization must be given from the Ministry of Public Health. To obtain such authorization, the manufacturer, introducer or trader, shall submit technical reports setting out the characteristics of the products or elements to be introduced into the country, the types of asbestos, measures to be taken to control risks to health, how waste will be disposed of and the justification that it is not possible to replace asbestos with another type of materials.', 'Decree No. 154/002 establishes that for the manufacture, introduction into the national territory under any form, and marketing of asbestos or products which contain it, authorization must be given from the Ministry of Public Health. To obtain such authorization, the manufacturer, introducer or trader, shall submit technical reports setting out the characteristics of the products or elements to be introduced into the country, the types of asbestos, measures to be taken to control risks to health, how waste will be disposed of and the justification that it is not possible to replace asbestos with another type of materials.', 'Decree No. 154/002 establishes that for the manufacture, introduction into the national territory under any form, and marketing of asbestos or products which contain it, authorization must be given from the Ministry of Public Health. To obtain such authorization, the manufacturer, introducer or trader, shall submit technical reports setting out the characteristics of the products or elements to be introduced into the country, the types of asbestos, measures to be taken to control risks to health, how waste will be disposed of and the justification that it is not possible to replace asbestos with another type of materials.', 'Uruguay', 'climate', 'in_force', '2002-01-01'::date, 'Uruguay', 'https://www.carrotsandsticks.org/policies/186_4', ARRAY['other sustainability policy', 'regulations', 'uruguay', 'mandatory', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2e407733-3365-52c4-82fe-b3bc2b340997', 'Uruguay Law .466 on Environmental Impact Assessment', 'Law No. 16.466 on Environmental Impact Assessment', 'The  Environmental Impact Evaluation constitutes a system to identify, prevent, supervise and control the negative environmental impact arising from investment projects. Relevant subjects, before they start their activities and operations, must follow a process of environmental certification. This will involve describing the proposed action and the background, reporting information that identifies any direct and indirect environmental impacts during the project, environmental risks, goals, monitoring and control plans. Provisions on mandatory information disclosure include: a) identification of the owners of the property where the project will take place; b) the project signed by the designated technician(s), with a detailed description of its content; c) the environmental impact assessment signed by the technician(s); and d) a summary of the project in easily understandable terms containing the essential features of it, as well as any impact that may derived from its execution.', 'The  Environmental Impact Evaluation constitutes a system to identify, prevent, supervise and control the negative environmental impact arising from investment projects. Relevant subjects, before they start their activities and operations, must follow a process of environmental certification. This will involve describing the proposed action and the background, reporting information that identifies any direct and indirect environmental impacts during the project, environmental risks, goals, monitoring and control plans. Provisions on mandatory information disclosure include: a) identification of the owners of the property where the project will take place; b) the project signed by the designated technician(s), with a detailed description of its content; c) the environmental impact assessment signed by the technician(s); and d) a summary of the project in easily understandable terms containing the essential features of it, as well as any impact that may derived from its execution.', 'The  Environmental Impact Evaluation constitutes a system to identify, prevent, supervise and control the negative environmental impact arising from investment projects. Relevant subjects, before they start their activities and operations, must follow a process of environmental certification. This will involve describing the proposed action and the background, reporting information that identifies any direct and indirect environmental impacts during the project, environmental risks, goals, monitoring and control plans. Provisions on mandatory information disclosure include: a) identification of the owners of the property where the project will take place; b) the project signed by the designated technician(s), with a detailed description of its content; c) the environmental impact assessment signed by the technician(s); and d) a summary of the project in easily understandable terms containing the essential features of it, as well as any impact that may derived from its execution.', 'Uruguay', 'climate', 'in_force', '1994-01-01'::date, 'Uruguay', 'https://www.carrotsandsticks.org/policies/186_3', ARRAY['uruguay', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fefeed66-1259-5203-a47b-dbf6fd35ee12', 'Venezuela Decree 2,635 Standards for the Control of Recovery', 'Decree 2,635 Standards for the Control of Recovery of Hazardous Materials and Management of Hazardous Waste (July 22, 1998)', 'The purpose of this decree is to regulate the recovery of materials and the management of waste, when they present characteristics, composition or dangerous conditions, representing a source of risk to health and the environment. It includes, among other areas: general provisions; of recoverable hazardous materials and hazardous waste, their characteristics and hazardous conditions; management of hazardous waste, with special reference to the activities of exploration and production of oil and mineral exploitation; administrative control of hazardous waste handlers. It also includes various annexes: list of activities that potentially generate recoverable hazardous materials and hazardous waste, hazardous waste and recoverable hazardous materials from non-specific activities.', 'The purpose of this decree is to regulate the recovery of materials and the management of waste, when they present characteristics, composition or dangerous conditions, representing a source of risk to health and the environment. It includes, among other areas: general provisions; of recoverable hazardous materials and hazardous waste, their characteristics and hazardous conditions; management of hazardous waste, with special reference to the activities of exploration and production of oil and mineral exploitation; administrative control of hazardous waste handlers. It also includes various annexes: list of activities that potentially generate recoverable hazardous materials and hazardous waste, hazardous waste and recoverable hazardous materials from non-specific activities.', 'The purpose of this decree is to regulate the recovery of materials and the management of waste, when they present characteristics, composition or dangerous conditions, representing a source of risk to health and the environment. It includes, among other areas: general provisions; of recoverable hazardous materials and hazardous waste, their characteristics and hazardous conditions; management of hazardous waste, with special reference to the activities of exploration and production of oil and mineral exploitation; administrative control of hazardous waste handlers. It also includes various annexes: list of activities that potentially generate recoverable hazardous materials and hazardous waste, hazardous waste and recoverable hazardous materials from non-specific activities.', 'Venezuela', 'climate', 'in_force', '1998-01-01'::date, 'Venezuela', 'https://www.carrotsandsticks.org/policies/189_1', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'venezuela', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ecd6c59-80de-502a-940f-8dad437c919f', 'Venezuela Decree - Standards for the Classification and Quality', 'Decree No. 883 - Standards for the Classification and Quality Control of Water Bodies and Discharges or Liquid Effluents', 'This Decree approves the Standards for the Classification and Quality Control of Water Bodies and Discharges or Liquid Effluents. It is provided that the National Executive by means of a Decree will establish the classification corresponding to each body of water or sectors thereof, and in these specific regulations on discharges may be established, in accordance with the special conditions of the body of water object of the classification. Likewise, it will be able to establish an order of priorities for the classification of water bodies, according to the intensity of the degree of intervention or degradation of its waters. The bodies of water that have not been subject to classification will be governed by the general provisions established in this Decree.', 'This Decree approves the Standards for the Classification and Quality Control of Water Bodies and Discharges or Liquid Effluents. It is provided that the National Executive by means of a Decree will establish the classification corresponding to each body of water or sectors thereof, and in these specific regulations on discharges may be established, in accordance with the special conditions of the body of water object of the classification. Likewise, it will be able to establish an order of priorities for the classification of water bodies, according to the intensity of the degree of intervention or degradation of its waters. The bodies of water that have not been subject to classification will be governed by the general provisions established in this Decree.', 'This Decree approves the Standards for the Classification and Quality Control of Water Bodies and Discharges or Liquid Effluents. It is provided that the National Executive by means of a Decree will establish the classification corresponding to each body of water or sectors thereof, and in these specific regulations on discharges may be established, in accordance with the special conditions of the body of water object of the classification. Likewise, it will be able to establish an order of priorities for the classification of water bodies, according to the intensity of the degree of intervention or degradation of its waters. The bodies of water that have not been subject to classification will be governed by the general provisions established in this Decree.', 'Venezuela', 'governance', 'in_force', '1995-01-01'::date, 'Venezuela', 'https://www.carrotsandsticks.org/policies/189_2', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'venezuela']::text[]) ON CONFLICT (id) DO NOTHING;
